<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:11px;margin:32px}h1{color:#172554;margin:0 0 4px;font-size:28px}.muted{color:#64748b}.hero{background:#172554;color:white;padding:22px;border-radius:12px;margin-bottom:18px}.cards{display:flex;gap:10px;margin-bottom:18px}.card{flex:1;background:#f1f5f9;padding:14px;border-radius:8px}.label{color:#64748b;font-size:10px}.value{font-size:18px;font-weight:bold;margin-top:8px}table{width:100%;border-collapse:collapse}th{background:#312e81;color:white;text-align:left;padding:9px}td{padding:9px;border-bottom:1px solid #e2e8f0}td.num,th.num{text-align:right}.profit{color:#059669;font-weight:bold}.total td{font-weight:bold;background:#f8fafc}</style></head><body><div class="hero"><h1 style="color:white">Profit &amp; Loss</h1><div>{{ \Carbon\Carbon::parse($from)->format('M d, Y') }} - {{ \Carbon\Carbon::parse($until)->format('M d, Y') }} | {{ $currency === 'all' ? 'All currencies' : $currency }}</div></div><div class="cards"><div class="card"><div class="label">REVENUE</div><div class="value">${{ number_format($report['revenue'], 2) }}</div></div><div class="card"><div class="label">COST OF GOODS SOLD</div><div class="value">${{ number_format($report['cost'], 2) }}</div></div><div class="card"><div class="label">GROSS PROFIT</div><div class="value profit">${{ number_format($report['profit'], 2) }}</div></div><div class="card"><div class="label">MARGIN</div><div class="value">{{ number_format($report['margin'], 2) }}%</div></div></div><table><thead><tr><th>Product</th><th>Variant</th><th class="num">Qty</th><th class="num">Revenue</th><th class="num">Cost</th><th class="num">Profit</th></tr></thead><tbody>@foreach($report['items'] as $item)<tr><td>{{ $item['product_name'] }}</td><td>{{ $item['variant_label'] }}</td><td class="num">{{ $item['quantity'] }}</td><td class="num">${{ number_format($item['revenue'],2) }}</td><td class="num">${{ number_format($item['cost'],2) }}</td><td class="num profit">${{ number_format($item['profit'],2) }}</td></tr>@endforeach</tbody><tfoot><tr class="total"><td colspan="3">TOTAL</td><td class="num">${{ number_format($report['revenue'],2) }}</td><td class="num">${{ number_format($report['cost'],2) }}</td><td class="num profit">${{ number_format($report['profit'],2) }}</td></tr></tfoot></table></body></html>
